"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { useControllableState } from "../lib/hooks";

export interface FilterPanelProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title?: React.ReactNode;
  /** Aantal actieve filters; toont de wisknop zodra het meer dan nul is. */
  activeCount?: number;
  /** Wist alle filters. */
  onClear?: () => void;
  clearLabel?: string;
  /** Donkere rail, zoals de ingeklapte Sidebar. */
  tone?: "surface" | "inverted";
}

export interface FilterGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onToggle"> {
  label: React.ReactNode;
  /** Inklapbaar maken. */
  collapsible?: boolean;
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Toont zoveel opties en zet de rest achter "toon meer". */
  maxVisible?: number;
  moreLabel?: string;
  lessLabel?: string;
}

export interface FilterOptionProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "onChange"> {
  label: React.ReactNode;
  /** Vinkje of bolletje. */
  type?: "checkbox" | "radio";
  checked?: boolean;
  /** Deels aangevinkt, bv. een groep met een deel van de kinderen aan. */
  indeterminate?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  /** Aantal resultaten rechts. */
  count?: number;
  /** Avatar of icoontje voor het label. */
  lead?: React.ReactNode;
}

/** FilterPanel — kolom met filtergroepen, met een kop en een wisknop. */
export const FilterPanel = React.forwardRef<HTMLDivElement, FilterPanelProps>(function FilterPanel(
  { title, activeCount = 0, onClear, clearLabel = "Wissen", tone = "surface", className, children, ...rest },
  ref
) {
  return (
    <div ref={ref} data-tone={tone} className={cn("lui-filter", className)} {...rest}>
      {(title || (activeCount > 0 && onClear)) && (
        <div className="lui-filter-head">
          <span className="lui-filter-title">
            {title}
            {activeCount > 0 && <span className="lui-filter-count">{activeCount}</span>}
          </span>
          {activeCount > 0 && onClear && (
            <button type="button" className="lui-filter-clear" onClick={onClear}>
              {clearLabel}
            </button>
          )}
        </div>
      )}
      {children}
    </div>
  );
});

/** Eén groep filters, eventueel inklapbaar en met "toon meer". */
export const FilterGroup = React.forwardRef<HTMLDivElement, FilterGroupProps>(function FilterGroup(
  {
    label,
    collapsible,
    defaultOpen = true,
    open,
    onOpenChange,
    maxVisible,
    moreLabel = "Toon meer",
    lessLabel = "Toon minder",
    className,
    children,
    ...rest
  },
  ref
) {
  const [uitgeklapt, setUitgeklapt] = useControllableState<boolean>({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const [alles, setAlles] = React.useState(false);

  const items = React.Children.toArray(children);
  const verborgen = maxVisible !== undefined && items.length > maxVisible && !alles;
  const zichtbaar = verborgen ? items.slice(0, maxVisible) : items;

  return (
    <div ref={ref} data-open={uitgeklapt ? "" : undefined} className={cn("lui-filter-group", className)} {...rest}>
      {collapsible ? (
        <button
          type="button"
          className="lui-filter-group-label"
          aria-expanded={uitgeklapt}
          onClick={() => setUitgeklapt(!uitgeklapt)}
        >
          {label}
          <Icon name="chevronDown" size={15} className="lui-filter-chevron" />
        </button>
      ) : (
        <div className="lui-filter-group-label">{label}</div>
      )}

      {(!collapsible || uitgeklapt) && (
        <div className="lui-filter-items">
          {zichtbaar}
          {maxVisible !== undefined && items.length > maxVisible && (
            <button type="button" className="lui-filter-more" onClick={() => setAlles((vorig) => !vorig)}>
              {alles ? lessLabel : `${moreLabel} (${items.length - maxVisible})`}
            </button>
          )}
        </div>
      )}
    </div>
  );
});

/** Eén filteroptie: vinkje of bolletje, met tellertje en optioneel een avatar. */
export const FilterOption = React.forwardRef<HTMLInputElement, FilterOptionProps>(
  function FilterOption(
    { label, type = "checkbox", checked, indeterminate, onCheckedChange, count, lead, className, disabled, ...rest },
    ref
  ) {
    const eigen = React.useRef<HTMLInputElement | null>(null);

    React.useEffect(() => {
      if (eigen.current) eigen.current.indeterminate = Boolean(indeterminate);
    }, [indeterminate]);

    return (
      <label className={cn("lui-filter-option", className)} data-disabled={disabled ? "" : undefined}>
        <input
          ref={(node) => {
            eigen.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as React.RefObject<HTMLInputElement | null>).current = node;
          }}
          type={type}
          className="lui-filter-input"
          checked={checked}
          disabled={disabled}
          onChange={(event) => onCheckedChange?.(event.target.checked)}
          {...rest}
        />
        <span className="lui-filter-box" aria-hidden="true">
          <Icon name={indeterminate ? "minus" : "check"} size={12} strokeWidth={3} />
        </span>
        {lead && <span className="lui-filter-lead">{lead}</span>}
        <span className="lui-filter-label">{label}</span>
        {count !== undefined && <span className="lui-filter-badge">{count}</span>}
      </label>
    );
  }
);

/* ============================ FilterPanel ============================ */
.lui-filter {
  display: flex; flex-direction: column; gap: 4px;
  width: 100%; max-width: 280px; padding: calc(14px * var(--density)) 14px;
  border: 1px solid var(--border); border-radius: var(--r-lg);
  background: var(--surface);
}
.lui-filter[data-tone="inverted"] {
  background: var(--sidebar-ink); border-color: var(--sidebar-ink-border); color: var(--sidebar-ink-text);
}

.lui-filter-head { display: flex; align-items: center; gap: 8px; padding: 2px 6px 10px; }
.lui-filter-title {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: var(--fs-md); font-weight: 650; color: var(--text); letter-spacing: -0.01em;
}
.lui-filter[data-tone="inverted"] .lui-filter-title { color: var(--sidebar-ink-strong); }
.lui-filter-count {
  display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 6px;
  border-radius: var(--r-full); background: var(--accent); color: var(--accent-fg);
  font-size: 11.5px; font-weight: 700;
}
.lui-filter-clear {
  margin-left: auto; border: 0; background: none; padding: 4px 6px; border-radius: var(--r-xs);
  font: inherit; font-size: var(--fs-sm); font-weight: 600; color: var(--accent); cursor: pointer;
}
.lui-filter-clear:hover { background: var(--accent-tint); }
.lui-filter-clear:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-filter-group { padding: 6px 0; border-top: 1px solid var(--border); }
.lui-filter-group:first-of-type { border-top: 0; }
.lui-filter[data-tone="inverted"] .lui-filter-group { border-color: var(--sidebar-ink-border); }
.lui-filter-group-label {
  display: flex; align-items: center; gap: 8px; width: 100%;
  padding: 7px 6px; border: 0; background: none; text-align: left;
  font: inherit; font-size: 11.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase;
  color: var(--text-3); cursor: default;
}
button.lui-filter-group-label { cursor: pointer; }
button.lui-filter-group-label:focus-visible { outline: none; box-shadow: var(--ring); border-radius: var(--r-xs); }
.lui-filter-chevron { margin-left: auto; transition: transform var(--dur) var(--ease); }
.lui-filter-group[data-open] .lui-filter-chevron { transform: rotate(180deg); }
.lui-filter-items { display: flex; flex-direction: column; gap: 1px; }

.lui-filter-option {
  display: flex; align-items: center; gap: 10px;
  padding: calc(7px * var(--density)) 8px; border-radius: var(--r-sm);
  font-size: var(--fs-base); color: var(--text); cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}
.lui-filter-option:hover { background: var(--surface-3); }
.lui-filter[data-tone="inverted"] .lui-filter-option { color: var(--sidebar-ink-text); }
.lui-filter[data-tone="inverted"] .lui-filter-option:hover { background: var(--sidebar-ink-hover); }
.lui-filter-option[data-disabled] { opacity: .5; cursor: not-allowed; }

.lui-filter-input { position: absolute; opacity: 0; width: 0; height: 0; }
.lui-filter-box {
  display: grid; place-items: center; width: 17px; height: 17px; flex: none;
  border: 1.5px solid var(--border-strong); border-radius: 5px; background: var(--surface);
  color: transparent; transition: background var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease);
}
.lui-filter-input[type="radio"] ~ .lui-filter-box { border-radius: var(--r-full); }
.lui-filter-input:checked ~ .lui-filter-box,
.lui-filter-input:indeterminate ~ .lui-filter-box {
  background: var(--accent); border-color: var(--accent); color: var(--accent-fg);
}
.lui-filter-input:focus-visible ~ .lui-filter-box { box-shadow: var(--ring); }
.lui-filter-lead { display: inline-flex; flex: none; }
.lui-filter-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lui-filter-badge {
  flex: none; font-size: var(--fs-xs); color: var(--text-3); font-variant-numeric: tabular-nums;
}
